import { readFileSync, writeFileSync } from "node:fs";
// Embed the licensed font in a server-only module so serverless tracing cannot
// omit it. This module is never imported by the browser application.
const encoded = readFileSync("server/fonts/DejaVuSans.ttf").toString("base64");
const license = readFileSync("server/fonts/LICENSE", "utf8");
writeFileSync(
  "server/pdf-font.ts",
  "// Generated by scripts/embed-font.mjs. Do not edit by hand.\nexport const fontLicense = " +
    JSON.stringify(license) +
    ";\nexport const pdfFont = Buffer.from(" +
    JSON.stringify(encoded) +
    ', "base64");\n',
);
